                { name = "召喚傳送門", nameEn = "Portal of Summoning", icon = "Interface\\Icons\\Inv_Misc_Rune_10", id = 437169, status = "new", learnLv = 60, races = "", reason = "經典舊世沒有；探索賽季有同名法術", cost = "100%基礎法力值", range = "30碼距離", cast = "需引導", cd = "1小時冷卻時間", desc = "開啓一個儀式，製造出一道傳送門。2名團隊成員就可以使用這道傳送門來召喚隊友。儀式需要施法者和2名隊友協力才能完成。所有參與召喚的隊友都必須不在戰鬥狀態中，使用右鍵點擊傳送門，並且在召喚完成之前不得移動。", isTalent = false },
                { name = "末日儀式", nameEn = "Ritual of Doom", icon = "Interface\\Icons\\Spell_Shadow_Antimagicshell", id = 18540, status = "same", learnLv = 60, races = "", reason = "", cost = "100%基礎法力值", range = "30碼距離", cast = "需引導", cd = "1小時冷卻時間", desc = "進行祭祀儀式，隨機犧牲一個參與者以召喚出一個末日守衛。你必須立即征服末日守衛，否則它就會攻擊參與儀式者。需要施法者和4個隊友共同進行儀式，所有參與者都必須使用右鍵點擊傳送門，在完成儀式之前不得移動。", isTalent = false },
                { name = "惡魔犧牲", nameEn = "Demonic Sacrifice", icon = "Interface\\Icons\\Spell_Shadow_Psychicscream", id = 18788, status = "talent", learnLv = nil, races = "", reason = "天賦：投入天賦點數即可獲得，訓練師不教；經典舊世中也是天賦", cost = "", range = "100碼距離", cast = "瞬發", cd = "", desc = "激活後，犧牲你召喚的惡魔來強化你力量的相反面向，使你獲得一個持續2小時的效果。如果召喚任何惡魔，該效果會被取消。\n\n小鬼：使你的暗影傷害提高15%。\n\n虛空行者：每4秒恢復總法力值的2%。\n\n魅魔/夜魔：使你的火焰傷害提高15%。\n\n地獄獵犬：每4秒恢復總生命值的3%。", classic = "激活之後，犧牲你當前所召喚的惡魔，使你獲得一種特殊效果，持續30分鐘。如果在此期間你召喚任意一個惡魔，該效果就會被取消。\n\n小鬼：使你的火焰技能傷害提高15%。\n\n虛空行者：使你每4秒回覆3%的生命值。\n\n魅魔/夜魔：使你的暗影技能傷害提高15%。\n\n地獄犬：使你每4秒回覆2%的法力值。", isTalent = true },
                { name = "惡魔支配", nameEn = "Fel Domination", icon = "Interface\\Icons\\Spell_Nature_Removecurse", id = 18708, status = "talent", learnLv = nil, races = "", reason = "天賦：投入天賦點數即可獲得，訓練師不教；經典舊世中也是天賦", cost = "", range = "", cast = "瞬發", cd = "5分鐘冷卻時間", desc = "你的下一個召喚小鬼、虛空行者、魅魔、夜魔或地獄獵犬的法術施法時間減少5.5秒，法力消耗減少50%。", isTalent = true },
                { name = "靈魂鏈接", nameEn = "Soul Link", icon = "Interface\\Icons\\Spell_Shadow_Gathershadows", id = 19028, status = "talent", learnLv = nil, races = "", reason = "天賦：投入天賦點數即可獲得，訓練師不教；經典舊世中也是天賦", cost = "20%基礎法力值", range = "100碼距離", cast = "瞬發", cd = "", desc = "激活時，施法者受到的所有傷害有30%由你的小鬼、虛空行者、魅魔、夜魔或地獄獵犬惡魔承受。此外，惡魔和主人造成的傷害都提高3%。只要惡魔處於激活狀態，該效果就會持續。", classic = "激活之後，施法者所承受的傷害有30%被你的小鬼、虛空行者、魅魔、地獄獵犬、惡魔衛士等惡魔分擔。另外，惡魔和其主人的任何攻擊所造成的傷害都提高3%。只要惡魔保持激活狀態，該效果就一直持續。", isTalent = true },
